import unittest
import sys
from candidate import fibfib

class TestFibFib(unittest.TestCase):
    def test_fibfib_zero_returns_zero(self):
        self.assertEqual(fibfib(0), 0)

    def test_fibfib_one_returns_zero(self):
        self.assertEqual(fibfib(1), 0)

    def test_fibfib_two_returns_one(self):
        self.assertEqual(fibfib(2), 1)

    def test_fibfib_three_returns_one(self):
        self.assertEqual(fibfib(3), 1)

    def test_fibfib_four_returns_two(self):
        self.assertEqual(fibfib(4), 2)

    def test_fibfib_five_returns_four(self):
        self.assertEqual(fibfib(5), 4)

    def test_fibfib_six_returns_seven(self):
        self.assertEqual(fibfib(6), 7)

    def test_fibfib_seven_returns_thirteen(self):
        self.assertEqual(fibfib(7), 13)

    def test_fibfib_eight_returns_twenty_four(self):
        self.assertEqual(fibfib(8), 24)

    def test_fibfib_nine_returns_forty_four(self):
        self.assertEqual(fibfib(9), 44)

    def test_fibfib_ten_returns_eighty(self):
        self.assertEqual(fibfib(10), 80)

    def test_fibfib_eleven_returns_one_hundred_forty_one(self):
        self.assertEqual(fibfib(11), 141)

    def test_fibfib_return_type_is_int(self):
        self.assertIsInstance(fibfib(5), int)

    def test_fibfib_sequence_is_monotonically_nondecreasing(self):
        prev = fibfib(0)
        for i in range(1, 10):
            curr = fibfib(i)
            self.assertGreaterEqual(curr, prev)
            prev = curr

    def test_fibfib_recurrence_relation_holds(self):
        for n in range(3, 10):
            expected = fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)
            self.assertEqual(fibfib(n), expected)

    def test_fibfib_with_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            fibfib(None)

    def test_fibfib_with_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            fibfib("5")

    def test_fibfib_with_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            fibfib([1, 2, 3])

    def test_fibfib_with_negative_raises_recursion_error(self):
        old_limit = sys.getrecursionlimit()
        sys.setrecursionlimit(100)
        try:
            with self.assertRaises(RecursionError):
                fibfib(-1)
        finally:
            sys.setrecursionlimit(old_limit)

    def test_fibfib_with_negative_two_raises_recursion_error(self):
        old_limit = sys.getrecursionlimit()
        sys.setrecursionlimit(100)
        try:
            with self.assertRaises(RecursionError):
                fibfib(-2)
        finally:
            sys.setrecursionlimit(old_limit)

    def test_fibfib_zero_float_returns_zero(self):
        self.assertEqual(fibfib(0.0), 0)

    def test_fibfib_two_float_returns_one(self):
        self.assertEqual(fibfib(2.0), 1)

    def test_fibfib_bool_true_returns_zero(self):
        self.assertEqual(fibfib(True), 0)

    def test_fibfib_bool_false_returns_zero(self):
        self.assertEqual(fibfib(False), 0)

if __name__ == '__main__':
    unittest.main()
